import { HugeiconsIcon } from "@hugeicons/react";
import BadgeCheckIcon from "@hugeicons/core-free-icons/BadgeCheckIcon";
import ChevronRightIcon from "@hugeicons/core-free-icons/ChevronRightIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemMedia,
  ItemTitle,
} from "@/registry/erbium/ui/item";

export default function ItemSizeDemo() {
  return (
    <div className="flex w-full max-w-md flex-col gap-6">
      <Item variant="card">
        <ItemContent>
          <ItemTitle>Basic Item</ItemTitle>
          <ItemDescription>A simple item with title and description.</ItemDescription>
        </ItemContent>
        <ItemActions>
          <Button variant="outline" size="sm">
            Action
          </Button>
        </ItemActions>
      </Item>
      <Item
        variant="card"
        size="sm"
        render={
          <a href="#">
            <ItemMedia>
              <HugeiconsIcon icon={BadgeCheckIcon} className="size-5" />
            </ItemMedia>
            <ItemContent>
              <ItemTitle>Your profile has been verified.</ItemTitle>
            </ItemContent>
            <ItemActions>
              <HugeiconsIcon icon={ChevronRightIcon} className="size-4" />
            </ItemActions>
          </a>
        }
      />
    </div>
  );
}

import ExampleItemSize from "../examples/item-size";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleItemSize />
  </div>
);

export default Example;
